settings.custom_liquid:
{% comment %}
  ARTPIXE — Trust Badges i18n
  Langues : FR · EN · ES · DE · IT
{% endcomment %}

{% assign lang = localization.language.iso_code | default: request.locale.iso_code | default: shop.locale %}
{% case lang %}
  {% when 'en' %}{% assign tp_avis = '31 reviews' %}{% assign lx_avis = '350 reviews' %}
  {% when 'es' %}{% assign tp_avis = '31 opiniones' %}{% assign lx_avis = '350 opiniones' %}
  {% when 'de' %}{% assign tp_avis = '31 Bewertungen' %}{% assign lx_avis = '350 Bewertungen' %}
  {% when 'it' %}{% assign tp_avis = '31 recensioni' %}{% assign lx_avis = '350 recensioni' %}
  {% else %}{% assign tp_avis = '31 avis' %}{% assign lx_avis = '350 avis' %}
{% endcase %}

<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap');

/* Reset Kalles — seulement sur les liens */
.apx-tb,
.apx-tb:hover,
.apx-tb:focus,
.apx-tb:active,
.apx-tb:visited {
  box-shadow: none !important;
  outline: none !important;
  text-decoration: none !important;
  background-image: none !important;
}

/* Container */
.apx-trust-wrap {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  flex-wrap: nowrap;
  gap: 8px;
  margin-bottom: 16px;
  font-family: 'DM Sans', sans-serif;
}

/* Badge commun */
.apx-tb {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 8px 8px;
  border-radius: 10px;
  cursor: pointer;
  white-space: nowrap;
  min-width: 0;
  overflow: hidden;
  font-size: 11px;
}

/* Trustpilot — vert */
.apx-tb--tp {
  background: rgba(0,182,122,.15);
  border: 1.5px solid rgba(0,182,122,.4) !important;
  border-bottom: 1.5px solid rgba(0,182,122,.4) !important;
}

/* Loox — orange */
.apx-tb--lx {
  background: rgba(245,166,35,.12);
  border: 1.5px solid rgba(245,166,35,.35) !important;
  border-bottom: 1.5px solid rgba(245,166,35,.35) !important;
}

/* Étoile icône */
.apx-tb__star-ico { font-size: 11px; line-height: 1; flex-shrink: 0; }
.apx-tb--tp .apx-tb__star-ico { color: #00B67A; }
.apx-tb--lx .apx-tb__star-ico { color: #f5a623; }

/* Nom */
.apx-tb__name { font-size: 11px; font-weight: 700; line-height: 1; }
.apx-tb--tp .apx-tb__name { color: #00e89b; }
.apx-tb--lx .apx-tb__name { color: #f5a623; }

/* Séparateur */
.apx-tb__dot { font-size: 10px; color: rgba(255,255,255,.25); line-height: 1; }

/* Score */
.apx-tb__score { font-size: 11px; font-weight: 700; color: #f0ede8; line-height: 1; }

/* Count */
.apx-tb__count { font-size: 10px; font-weight: 400; color: rgba(255,255,255,.5); line-height: 1; }

/* Étoiles Loox */
.apx-tb__stars-lx { font-size: 11px; color: #f5a623; letter-spacing: 0; line-height: 1; }

@media (min-width: 768px) {
  .apx-trust-wrap { gap: 12px; margin-bottom: 20px; }
  .apx-tb { padding: 11px 18px; gap: 8px; font-size: 14px; border-radius: 12px; }
  .apx-tb__star-ico { font-size: 16px; }
  .apx-tb__name { font-size: 14px; }
  .apx-tb__score { font-size: 14px; }
  .apx-tb__count { font-size: 13px; }
  .apx-tb__dot { font-size: 13px; }
  .apx-tb__stars-lx { font-size: 15px; letter-spacing: 1px; }
  .apx-tb--tp { background: rgba(0,182,122,.18); border: 1.5px solid rgba(0,182,122,.5) !important; border-bottom: 1.5px solid rgba(0,182,122,.5) !important; }
  .apx-tb--lx { background: rgba(245,166,35,.16); border: 1.5px solid rgba(245,166,35,.5) !important; border-bottom: 1.5px solid rgba(245,166,35,.5) !important; }
}
</style>

<div class="apx-trust-wrap">

  <a href="https://fr.trustpilot.com/review/artpixe.com" target="_blank" rel="noopener" class="apx-tb apx-tb--tp">
    <span class="apx-tb__star-ico">★</span>
    <span class="apx-tb__name">Trustpilot</span>
    <span class="apx-tb__dot">·</span>
    <span class="apx-tb__score">4,4/5</span>
    <span class="apx-tb__dot">·</span>
    <span class="apx-tb__count">{{ tp_avis }}</span>
  </a>

  <a href="https://loox.app/a/artpixe" target="_blank" rel="noopener" class="apx-tb apx-tb--lx">
    <span class="apx-tb__stars-lx">★★★★★</span>
    <span class="apx-tb__name">Loox</span>
    <span class="apx-tb__dot">·</span>
    <span class="apx-tb__count">{{ lx_avis }}</span>
  </a>

</div>

