    {%- assign t_strong = "Le tue foto" -%}
    {%- assign t_line   = "Puoi inviare <b>più foto</b>, singole o in gruppo." -%}
    {%- assign t_later  = "📎 Puoi inviare le tue foto in seguito via e-mail dopo l'ordine." -%}
  {%- else -%}
    {%- assign t_strong = "Vos photos" -%}
    {%- assign t_line   = "Vous pouvez envoyer <b>plusieurs photos</b>, séparées ou en groupe." -%}
    {%- assign t_later  = "📎 Vous pouvez envoyer vos photos plus tard par e-mail après la commande." -%}
