<div class="apx-stepbox">
  <div class="apx-stepbox__inner">
    <span class="apx-stepbox__num">1</span>
    <div class="apx-stepbox__body">
      <strong class="apx-stepbox__title">{{ t_strong }}</strong>
      <span class="apx-stepbox__desc">{{ t_line }}</span>
