  border-bottom: 1px solid rgba(255,255,255,.08) !important;
}

/* Numéro */
.apx-stepbox__num {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 800;
  color: #000;
  background: #f5a623;
  flex: 0 0 auto;
  line-height: 1;
}

/* Texte */
.apx-stepbox__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  line-height: 1.4;
}

.apx-stepbox__title {
  font-size: 14px;
  font-weight: 800;
  color: #f0ede8;
  line-height: 1.3;
}

.apx-stepbox__desc {
  font-size: 12.5px;
  color: #9a9690;
  line-height: 1.5;
}

.apx-stepbox__desc b {
  color: #f0ede8;
  font-weight: 700;
}

/* Mention photos plus tard */
.apx-stepbox__later {
