<style>
@import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=DM+Sans:wght@300;400;500&display=swap');

.apx-version-hidden {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 0 !important;
  pointer-events: none !important;
}

#apx-fmt {
  margin: 0 0 14px;
  font-family: 'DM Sans', sans-serif;
}
#apx-fmt .apx-label {
  font-size: 12px;
  font-weight: 500;
  color: #f0ede8;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 4px;
}
#apx-fmt .apx-lv { color: #f5a623; }

/* ── Grille 2×2 ── */
.apx-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 7px;
}

/* ── Wrapper ── */
.apx-wrap {
  position: relative;
  padding-top: 10px;
}

/* ── Carte ── */
.apx-card {
  background: #141416;
  border: 1.5px solid rgba(255,255,255,.07);
  border-radius: 10px;
  padding: 12px 10px 12px;
  text-align: center;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: border-color .18s, background .18s, transform .13s;
  -webkit-user-select: none;
  user-select: none;
  box-shadow: none !important;
  height: 100%;
}
.apx-card *, .apx-card *::before, .apx-card *::after {
  box-shadow: none !important;
  border-bottom: none !important;
}
.apx-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 90% 70% at 50% 0%, rgba(245,166,35,.07), transparent 70%);
  opacity: 0;
  transition: opacity .18s;
  pointer-events: none;
}
.apx-card:hover { border-color: rgba(245,166,35,.4); transform: translateY(-1px); }
.apx-card:hover::before { opacity: 1; }
.apx-card.apx-on { border-color: #f5a623; background: rgba(245,166,35,.05); }
.apx-card.apx-on::before { opacity: 1; }

/* ── Carte Displate — contour vert ── */
.apx-card-bs {
  border-color: #22c55e;
  background: rgba(34,197,94,.04);
}
.apx-card-bs::before {
  background: radial-gradient(ellipse 90% 70% at 50% 0%, rgba(34,197,94,.08), transparent 70%);
}
.apx-card-bs:hover {
  border-color: #22c55e;
  background: rgba(34,197,94,.07);
}
.apx-card-bs.apx-on {
  border-color: #22c55e;
  background: rgba(34,197,94,.07);
}

/* ── Carte Displate avec cadre — contour orange doré ── */
.apx-card-premium {
  border-color: rgba(245,166,35,.35);
  background: rgba(245,166,35,.03);
}
.apx-card-premium::before {
  background: radial-gradient(ellipse 90% 70% at 50% 0%, rgba(245,166,35,.1), transparent 70%);
}
.apx-card-premium:hover {
  border-color: rgba(245,166,35,.6);
  background: rgba(245,166,35,.06);
}
.apx-card-premium.apx-on {
  border-color: #f5a623;
  background: rgba(245,166,35,.07);
}

/* ── Badges ── */
.apx-bs-tag,
.apx-premium-tag {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  font-family: 'DM Sans', sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: #000;
  border-radius: 4px;
  padding: 2px 8px;
  white-space: nowrap;
  pointer-events: none;
}
.apx-bs-tag      { background: #22c55e; }
.apx-premium-tag { background: #f5a623; }

/* ── Check ── */
.apx-check {
  position: absolute;
  top: 7px; right: 7px;
  width: 15px; height: 15px;
  border-radius: 50%;
  background: #f5a623;
  display: flex; align-items: center; justify-content: center;
  opacity: 0; transform: scale(.4);
  transition: opacity .18s, transform .18s;
  z-index: 2;
}
.apx-card-bs .apx-check      { background: #22c55e; }
.apx-card-premium .apx-check { background: #f5a623; }
.apx-check svg { width: 8px; height: 8px; fill: none; stroke: #000; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
.apx-card.apx-on .apx-check { opacity: 1; transform: scale(1); }

/* ── Contenu ── */
.apx-ico  { font-size: 22px; display: block; margin-bottom: 5px; line-height: 1; }
.apx-name { font-family: 'Bebas Neue', sans-serif; font-size: 15px; letter-spacing: .04em; color: #f0ede8; margin-bottom: 5px; line-height: 1.05; }
.apx-desc { font-size: 10px; color: #7a7870; line-height: 1.45; margin: 0; font-weight: 300; }
</style>

<div id="apx-fmt">
  <p class="apx-label">{{ apx_label }} <span class="apx-lv" id="apx-lv">{{ apx_d_name }}</span></p>
  <div class="apx-grid" role="radiogroup">

    <!-- Digital -->
    <div class="apx-wrap">
      <div class="apx-card apx-on" data-fmt="Digital" data-label="{{ apx_d_name }}"
           role="radio" aria-checked="true" tabindex="0"
           onclick="apxPick(this)" onkeydown="if(event.key==='Enter'||event.key===' ')apxPick(this)">
        <div class="apx-check"><svg viewBox="0 0 12 12"><polyline points="2,6 5,9 10,3"/></svg></div>
        <span class="apx-ico">💻</span>
        <div class="apx-name">{{ apx_d_name }}</div>
        <p class="apx-desc">{{ apx_d_desc }}</p>
      </div>
    </div>

    <!-- Poster A3 -->
    <div class="apx-wrap">
      <div class="apx-card" data-fmt="Poster A3" data-label="{{ apx_p_name }}"
           role="radio" aria-checked="false" tabindex="0"
           onclick="apxPick(this)" onkeydown="if(event.key==='Enter'||event.key===' ')apxPick(this)">
        <div class="apx-check"><svg viewBox="0 0 12 12"><polyline points="2,6 5,9 10,3"/></svg></div>
