<script>
(function(){
  var section=document.getElementById('apx-reco');
  if(!section||section.dataset.apxInit==='1')return;
  section.dataset.apxInit='1';
  var track=document.getElementById('apx-reco-track');
  var dots=document.querySelectorAll('#apx-reco-dots .apx-reco__dot');
  var cards=track?track.querySelectorAll('.apx-reco__card'):[];
  if(!track||!dots.length||!cards.length)return;
  function onScroll(){var idx=Math.round(track.scrollLeft/(track.scrollWidth/cards.length));idx=Math.max(0,Math.min(idx,cards.length-1));dots.forEach(function(d,i){d.classList.toggle('active',i===idx);});cards.forEach(function(c,i){c.classList.toggle('is-active',i===idx);});}
  dots.forEach(function(dot){dot.addEventListener('click',function(){var card=cards[parseInt(this.dataset.idx,10)];if(card)track.scrollTo({left:card.offsetLeft-(track.offsetWidth-card.offsetWidth)/2,behavior:'smooth'});});});
  track.addEventListener('scroll',onScroll,{passive:true});
  onScroll();
})();
</script>

